import os, base64

# Each value is base64-encoded UTF-8 content
FILES = {
    'app/__init__.py': '',
    'app/models/__init__.py': '',
    'app/models/image.py': '',
    'app/services/__init__.py': '',
    'app/services/_language_detect.py': '',
    'app/services/_prompt_enhance.py': '',
    'app/services/_prompt_expand.py': '',
    'app/services/_storage.py': '',
    'app/services/add_image_to_collection.py': '',
    'app/services/batch_generate_images.py': '',
    'app/services/create_collection.py': '',
    'app/services/delete_collection.py': '',
    'app/services/enhance_prompt.py': '',
    'app/services/generate_image.py': '',
    'app/services/get_user_dashboard.py': '',
    'app/services/regenerate_image.py': '',
    'app/services/remove_image_from_collection.py': '',
    'app/urls.py': '',
    'app/views/__init__.py': '',
    'app/views/_auth.py': '',
    'app/views/_rate_limit.py': '',
    'app/views/add_image_to_collection.py': '',
    'app/views/batch_generate_images.py': '',
    'app/views/create_collection.py': '',
    'app/views/delete_collection.py': '',
    'app/views/enhance_prompt.py': '',
    'app/views/generate_image.py': '',
    'app/views/get_collection_detail.py': '',
    'app/views/get_user_dashboard.py': '',
    'app/views/list_collections.py': '',
    'app/views/regenerate_image.py': '',
    'app/views/remove_image_from_collection.py': '',
    'tests/collections/test_create_collection.py': '',
    'tests/generate/test_enhance_prompt.py': '',
    'tests/generate/test_generate_image.py': '',
    'tests/generate/test_language_detect.py': '',
}


def main():
    created = 0
    for path, b64content in FILES.items():
        path = path.replace("/", os.sep)
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        content = base64.b64decode(b64content).decode("utf-8")
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"  created: {path}")
        created += 1
    print("")
    print(f"Done — {created} files created successfully.")


if __name__ == "__main__":
    main()